/**
 * Slack Node - Version 2.6
 * Discriminator: resource=channel, operation=rename
 */


interface Credentials {
  slackApi: CredentialReference;
  slackOAuth2Api: CredentialReference;
}

/** Renames a conversation */
export type SlackV26ChannelRenameParams = {
  resource: 'channel';
  operation: 'rename';
  authentication?: 'accessToken' | 'oAuth2' | Expression<string>;
/**
 * The Slack channel to rename
 * @searchListMethod getChannels
 * @default {"mode":"list","value":""}
 */
    channelId?: { __rl: true; mode: 'list' | 'id' | 'url'; value: string; cachedResultName?: string };
/**
 * New name for conversation
 */
    name: string | Expression<string>;
};

export type SlackV26ChannelRenameNode = {
  type: 'n8n-nodes-base.slack';
  version: 2.6;
  config: NodeConfig<SlackV26ChannelRenameParams> & { credentials?: Credentials };
};